var i=[{title:`Liegestütz-Grundlagen`,text:`Setze die Hände dort auf, wo es sich bequem anfühlt, halte den Körper von den Schultern bis zur Hüfte in einer Linie, senke dich mit Ellenbogen in einem Winkel, den deine Schultern vertragen, und drücke den Boden weg. Deine Schulterblätter bewegen sich bei einem Liegestütz ganz natürlich um den Brustkorb herum. Lass die Hüfte nicht durchhängen und schiebe den Kopf nicht nach vorn, nur um eine Wiederholung zu zählen.`},{title:`Eine Variante wählen`,text:`Ein Wand-Liegestütz ist oft der leichteste. Danach kommt eine Schräge auf einer stabilen Arbeitsplatte oder Bank, dann ein Liegestütz auf den Knien oder ganz am Boden. Später kannst du die Füße erhöhen oder Last hinzufügen, um es schwerer zu machen. Ob die Knie- oder die Schrägvariante für dich leichter ist, hängt von Hebelwirkung und Komfort ab. Die Hände zu erhöhen ist eine einfache Möglichkeit, weniger deines Körpergewichts zu drücken.`},{title:`Bankdrücken und Kurzhanteldrücken`,text:`Stelle die Füße auf der Bank fest auf, bringe Rumpf und Schultern in eine stabile Position und senke die Gewichte kontrolliert ab. Eine Langhantel fixiert deine Hände, während Kurzhanteln den Griff freier bewegen lassen, aber auf jeder Seite Kontrolle verlangen. Schwere Versuche beim Bankdrücken brauchen einen fähigen Spotter oder passende Sicherheitsausrüstung.`},{title:`Häufige Missverständnisse`,text:`Deine Ellenbogen müssen nicht an den Rippen kleben, und sie sollten auch nicht immer gerade nach außen abstehen. Wähle eine Griffbreite und einen Ellenbogenweg, mit denen du dich kräftig und bequem bewegen kannst. Deine Schulterblätter bleiben nicht bei jeder Drückübung in einer Position festgefroren, und Liegestütze am Boden und Bankdrücken stellen unterschiedliche Anforderungen an sie.`},{title:`TrainUp nutzen`,text:`Bleibe bei einer Liegestütz-Variante und halte ihre Wiederholungen fest, bis du bereit bist weiterzugehen. Gleiche über die Woche das horizontale Drücken mit Zugarbeit aus. Wenn deine Handgelenke oder Schultern empfindlich sind, füge sie im Profil als Einschränkungen hinzu, damit dein Plan nur passende Druckübungen wählt.`}];var t=[{label:`ACE-Übungsbibliothek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: Technik beim Krafttraining (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`NSCA: Sicherheit und Grundlagen des Krafttrainings`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};